import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import { AuthContext } from '../../context/AuthContext';
import { Link, useNavigate } from 'react-router-dom';
import { List, ListItem, ListItemText, Typography, Paper, CircularProgress, Chip, Button, Box, Grid, Card, CardContent, Avatar } from '@mui/material';
import MedicalServicesIcon from '@mui/icons-material/MedicalServices';
import AssignmentIndIcon from '@mui/icons-material/AssignmentInd';
import EventNoteIcon from '@mui/icons-material/EventNote';

const NurseDashboard = () => {
    const { currentUser } = useContext(AuthContext);
    const navigate = useNavigate();
    const [pendingRequests, setPendingRequests] = useState([]);
    const [approvedRequests, setApprovedRequests] = useState([]);
    const [rejectedRequests, setRejectedRequests] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        if (currentUser && currentUser.accessToken) {
            fetchMedicationRequests();
        }
    }, [currentUser]);

    const fetchMedicationRequests = async () => {
        setLoading(true);
        setError(null);
        try {
            const token = localStorage.getItem('token');
            // Fetch pending requests
            const pendingRes = await axios.get('/api/medication-requests/pending', {
                headers: { Authorization: `Bearer ${token}` }
            });
            setPendingRequests(pendingRes.data || []);

            // Fetch approved requests
            const approvedRes = await axios.get('/api/medication-requests/status/APPROVED', {
                headers: { Authorization: `Bearer ${token}` }
            });
            setApprovedRequests(approvedRes.data || []);

            // Fetch rejected requests
            const rejectedRes = await axios.get('/api/medication-requests/status/REJECTED', {
                headers: { Authorization: `Bearer ${token}` }
            });
            setRejectedRequests(rejectedRes.data || []);

        } catch (err) {
            console.error("Error fetching medication requests:", err);
            setError('Failed to load medication requests. Please try again later.');
        } finally {
            setLoading(false);
        }
    };

    const getStatusChipColor = (status) => {
        switch (status.toLowerCase()) {
            case 'pending': return 'warning';
            case 'approved': return 'success';
            case 'rejected': return 'error';
            default: return 'default';
        }
    };

    const QuickActionCard = ({ title, count, icon, color, linkTo }) => (
        <Grid item xs={12} sm={6} md={4}>
            <Card sx={{ display: 'flex', flexDirection: 'column', height: '100%', transition: '0.3s', '&:hover': { boxShadow: 6, transform: 'translateY(-5px)' } }} component={Paper} elevation={3}>
                <CardContent sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center' }}>
                    <Avatar sx={{ bgcolor: color, width: 56, height: 56, mb: 2 }}>{icon}</Avatar>
                    <Typography variant="h6" component="div" gutterBottom>{title}</Typography>
                    <Typography variant="h4" color="text.primary" sx={{ mb: 1 }}>{count}</Typography>
                    {linkTo && (
                        <Button 
                            variant="contained" 
                            size="small" 
                            sx={{ mt: 'auto', bgcolor: color, '&:hover': { bgcolor: `${color}.dark` } }}
                            onClick={() => navigate(linkTo)}
                        >
                            View All
                        </Button>
                    )}
                </CardContent>
            </Card>
        </Grid>
    );

    const renderRequestList = (requests, title) => (
        <Paper elevation={2} sx={{ p: 2, mb: 3 }}>
            <Typography variant="h6" gutterBottom>{title} ({requests.length})</Typography>
            {requests.length === 0 ? (
                <Typography>No requests in this category.</Typography>
            ) : (
                <List dense>
                    {requests.slice(0, 5).map(req => (
                        <ListItem 
                            key={req.requestId} 
                            divider 
                            button 
                            onClick={() => navigate(`/nurse/medication-request/${req.requestId}`)}
                            sx={{ '&:hover': { backgroundColor: 'action.hover' } }}
                        >
                            <ListItemText 
                                primary={`${req.medicationName} for ${req.student.fullName}`}
                                secondary={`Parent: ${req.parent.user.firstName} ${req.parent.user.lastName} - Submitted: ${new Date(req.requestDate).toLocaleDateString()}`}
                            />
                            <Chip label={req.status} color={getStatusChipColor(req.status)} size="small" />
                        </ListItem>
                    ))}
                </List>
            )}
            {requests.length > 5 && (
                 <Button 
                    variant="text" 
                    size="small" 
                    sx={{ mt: 1 }}
                    // Potentially link to a page showing all requests of this type
                    onClick={() => navigate(`/nurse/medication-requests?status=${requests[0]?.status || ''}`)} 
                >
                    View all {title.toLowerCase()}
                </Button>
            )}
        </Paper>
    );

    if (loading) {
        return <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '80vh' }}><CircularProgress /></Box>;
    }

    if (error) {
        return <Typography color="error" sx={{ textAlign: 'center', mt: 4 }}>{error}</Typography>;
    }

    return (
        <Box sx={{ p: 3 }}>
            <Typography variant="h4" gutterBottom sx={{ mb: 3, fontWeight: 'bold', color: 'primary.main' }}>
                Nurse Dashboard
            </Typography>
            
            <Grid container spacing={3} sx={{ mb: 3 }}>
                <QuickActionCard title="Pending Medication Reviews" count={pendingRequests.length} icon={<MedicalServicesIcon />} color="#ff9800" linkTo="/nurse/medication-requests?status=PENDING" />
                <QuickActionCard title="Total Approved Today" count={approvedRequests.filter(r => new Date(r.actionDate).toDateString() === new Date().toDateString()).length} icon={<AssignmentIndIcon />} color="#4caf50" />
                <QuickActionCard title="Upcoming School Events" count={0} icon={<EventNoteIcon />} color="#2196f3" /> 
            </Grid>

            {renderRequestList(pendingRequests, 'Pending Medication Requests')}
            {/* Optionally show summaries of approved/rejected requests */}
            {/* {renderRequestList(approvedRequests, 'Recently Approved Requests')} */}
            {/* {renderRequestList(rejectedRequests, 'Recently Rejected Requests')} */}

            <Box sx={{ mt: 4, display: 'flex', justifyContent: 'center' }}>
                <Button variant="contained" onClick={() => navigate('/nurse/medication-requests/all')}>View All Medication Requests</Button>
            </Box>
        </Box>
    );
};

export default NurseDashboard;
